"""Trusted report body/envelope rendering for the shared run boundary."""

from __future__ import annotations

from tradingagents.reporting import _report_parts

from .checks import DISCLAIMER, NO_PORTFOLIO_NOTICE, render_provenance


def render_body(final_state: dict, context, redactor) -> tuple[str, list]:
    """Render narrative once, then redact it before checks and publication."""
    parts = _report_parts(final_state)
    sections = []
    for heading, _folder, written in parts:
        content = "\n\n".join(f"### {agent}\n{text}" for agent, _name, text in written)
        sections.append(f"## {heading}\n\n{content}")
    chunks = []
    if context.mode.value == "NO_PORTFOLIO":
        chunks.append(f"> {NO_PORTFOLIO_NOTICE}")
    if sections:
        chunks.extend(sections)
    else:
        chunks.append("## Analysis\n\nNo report sections were returned by the analysis workflow.")
    chunks.append(f"## Disclaimer\n\n{DISCLAIMER}")
    return redactor.scrub("\n\n".join(chunks)), parts


def build_envelope(metadata: dict, run_outcome: str, stop_reason: str | None,
                   final_rating: str | None, output_check: str,
                   findings: tuple, redactor) -> str:
    provenance = render_provenance(metadata)
    lines = [
        f"# Trading Analysis Report: {metadata['ticker']}", "", provenance,
        f"- Run outcome: {run_outcome}",
    ]
    if stop_reason:
        lines.append(f"- Stop reason: {stop_reason}")
    if final_rating is not None:
        lines.append(f"- Final Portfolio Manager rating: {final_rating}")
    lines.append(f"- Output check: {output_check}")
    if findings:
        lines.append("- Findings:")
        lines.extend(f"  - {finding.rule}: {finding.detail}" for finding in findings)
    return redactor.scrub("\n".join(lines) + "\n\n")


def verify_envelope_header_matches(envelope: str, trusted: dict) -> bool:
    """Check each trusted provenance line appears unchanged in the envelope."""
    return all(line in envelope.splitlines() for line in render_provenance(trusted).splitlines())

"""Immutable run identity and portfolio snapshot canonicalization."""

from __future__ import annotations

import hashlib
import json
import math
import re
import uuid
from dataclasses import dataclass
from datetime import UTC, datetime
from enum import StrEnum
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from tradingagents.portfolio import PortfolioContext


_RUN_ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}\Z")


def validate_run_id(run_id: str) -> str:
    # A run ID is stored directly as one filesystem path component.
    if not isinstance(run_id, str) or run_id in {".", ".."} or not _RUN_ID_RE.fullmatch(run_id):
        raise ValueError("run_id must be a safe single path component")
    return run_id


class InputMode(StrEnum):
    NO_PORTFOLIO = "NO_PORTFOLIO"
    PORTFOLIO_PROVIDED = "PORTFOLIO_PROVIDED"


class ConsentState(StrEnum):
    FROZEN = "FROZEN"
    CONFIRMED = "CONFIRMED"


@dataclass(frozen=True)
class FrozenSnapshot:
    basename: str
    cash: float | None
    currency: str | None
    positions: tuple[tuple[str, float, float | None], ...]
    fingerprint_sha256: str
    portfolio_as_of: str
    as_of_basis: str = "USER_CONFIRMED"

    def __post_init__(self):
        if not re.fullmatch(r"[0-9a-f]{64}", self.fingerprint_sha256):
            raise ValueError("snapshot fingerprint must be a full SHA-256 digest")
        object.__setattr__(self, "positions", tuple(tuple(row) for row in self.positions))

    def portfolio_context(self) -> PortfolioContext:
        from tradingagents.portfolio import PortfolioContext
        return PortfolioContext.model_validate({
            "cash": self.cash, "currency": self.currency,
            "positions": [
                {"ticker": ticker, "quantity": quantity, "average_price": average_price}
                for ticker, quantity, average_price in self.positions
            ],
        })


def _number(value: float | int | None):
    if value is None:
        return None
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("portfolio numbers must be finite")
    if number == 0:
        number = 0.0
    if number.is_integer() and abs(number) < 2**53:
        return int(number)
    return number


def canonical_portfolio(portfolio: PortfolioContext) -> tuple[dict, tuple[tuple[str, float, float | None], ...]]:
    rows = []
    for position in portfolio.positions:
        ticker = position.ticker.strip().upper()
        if not ticker:
            raise ValueError("portfolio ticker cannot be empty")
        quantity = float(position.quantity)
        average_price = None if position.average_price is None else float(position.average_price)
        row = {"ticker": ticker, "quantity": _number(quantity),
               "average_price": _number(average_price)}
        price_key = (0, 0.0) if average_price is None else (1, average_price)
        rows.append((ticker, quantity, average_price, row, price_key))
    rows.sort(key=lambda item: (item[0], item[1], item[4]))
    normalized = {
        "cash": _number(portfolio.cash),
        "currency": portfolio.currency,
        "positions": [item[3] for item in rows],
    }
    frozen_rows = tuple((ticker, quantity, price) for ticker, quantity, price, _, _ in rows)
    return normalized, frozen_rows


def snapshot_fingerprint(portfolio: PortfolioContext) -> tuple[str, tuple[tuple[str, float, float | None], ...]]:
    normalized, rows = canonical_portfolio(portfolio)
    raw = json.dumps(normalized, sort_keys=True, separators=(",", ":"),
                     ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(raw).hexdigest(), rows


@dataclass(frozen=True)
class RunContext:
    run_id: str
    ticker: str
    analysis_date: str
    mode: InputMode
    snapshot: FrozenSnapshot | None
    unverified_holdings: bool
    provider_transmission_disclosed: bool
    consent_state: ConsentState = ConsentState.FROZEN

    def __post_init__(self):
        if (self.mode == InputMode.NO_PORTFOLIO) != (self.snapshot is None):
            raise ValueError("snapshot must be absent exactly in NO_PORTFOLIO mode")
        validate_run_id(self.run_id)
        if not self.ticker.strip():
            raise ValueError("ticker is required")

    def confirm(self) -> RunContext:
        if self.consent_state != ConsentState.FROZEN:
            raise ValueError("only a frozen run context can be confirmed")
        return RunContext(
            self.run_id, self.ticker, self.analysis_date, self.mode, self.snapshot,
            self.unverified_holdings, self.provider_transmission_disclosed,
            ConsentState.CONFIRMED,
        )

    def portfolio_context(self) -> PortfolioContext | None:
        return self.snapshot.portfolio_context() if self.snapshot else None

    def safe_input_metadata(self) -> dict:
        snapshot = self.snapshot
        return {
            "run_id": self.run_id, "ticker": self.ticker,
            "analysis_date": self.analysis_date, "input_mode": self.mode.value,
            "basename": snapshot.basename if snapshot else None,
            "fingerprint_sha256": snapshot.fingerprint_sha256 if snapshot else None,
            "portfolio_as_of": snapshot.portfolio_as_of if snapshot else None,
            "as_of_basis": snapshot.as_of_basis if snapshot else None,
        }


def new_run_id(now: datetime | None = None) -> str:
    stamp = (now or datetime.now(UTC)).astimezone(UTC).strftime("%Y%m%dT%H%M%SZ")
    return f"{stamp}-{uuid.uuid4().hex[:8]}"

"""Typed results and errors for the shared run boundary."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal

InputErrorKind = Literal[
    "MALFORMED_JSON", "MISSING_POSITIONS", "MISSING_QUANTITY", "NONFINITE_NUMBER",
    "WRONG_SCALAR_TYPE", "UNREADABLE_PATH", "AS_OF_MISMATCH", "FLAG_CONFLICT",
]
StopReason = Literal[
    "MODEL_FAILURE", "DATA_FAILURE", "INTERNAL_ERROR", "PERSISTENCE_ERROR", "INTERRUPTED",
]
OutputCheck = Literal["PASSED", "NEEDS_REVIEW", "NOT_RUN"]
RunOutcome = Literal["COMPLETED", "INCOMPLETE"]
Rating = Literal["Buy", "Overweight", "Hold", "Underweight", "Sell", "REVIEW"]


class InputError(ValueError):
    """Safe, structured input failure; detail must never contain file contents."""

    def __init__(self, kind: InputErrorKind, detail: str, basename: str | None = None,
                 field: str | None = None):
        self.kind = kind
        self.basename = basename
        self.field = field
        self.detail = detail
        super().__init__(detail)

    def as_dict(self) -> dict:
        return {"kind": self.kind, "basename": self.basename, "field": self.field,
                "detail": self.detail}


@dataclass(frozen=True)
class Finding:
    rule: Literal["Q1", "Q2", "Q3", "Q4", "CHECK_ERROR"]
    status: Literal["BLOCKING"] = "BLOCKING"
    detail: str = ""

    def as_dict(self) -> dict:
        return {"rule": self.rule, "status": self.status, "detail": self.detail}


@dataclass(frozen=True)
class CheckResult:
    output_check: OutputCheck
    findings: tuple[Finding, ...] = field(default_factory=tuple)

    def __post_init__(self):
        if self.output_check == "PASSED" and self.findings:
            raise ValueError("PASSED check cannot contain findings")
        if self.output_check == "NEEDS_REVIEW" and not self.findings:
            raise ValueError("NEEDS_REVIEW requires at least one finding")
        if self.output_check == "NOT_RUN" and self.findings:
            raise ValueError("NOT_RUN cannot contain findings")

    def as_dict(self) -> dict:
        return {"output_check": self.output_check,
                "findings": [finding.as_dict() for finding in self.findings]}


@dataclass(frozen=True)
class RunResult:
    run_id: str
    ticker: str
    analysis_date: str
    input_mode: Literal["NO_PORTFOLIO", "PORTFOLIO_PROVIDED"]
    run_outcome: RunOutcome
    stop_reason: StopReason | None
    final_rating: Rating | None
    output_check: OutputCheck
    findings: tuple[Finding, ...] = field(default_factory=tuple)
    manifest_path: str | None = None
    report_path: str | None = None

    def __post_init__(self):
        if self.run_outcome == "COMPLETED":
            if self.final_rating is None or self.stop_reason is not None:
                raise ValueError("COMPLETED requires a rating and no stop reason")
            if self.output_check == "NOT_RUN":
                raise ValueError("COMPLETED cannot have NOT_RUN output check")
            if (self.output_check == "PASSED") != (len(self.findings) == 0):
                raise ValueError("Completed check status and findings disagree")
        else:
            if self.final_rating is not None or self.stop_reason is None:
                raise ValueError("INCOMPLETE requires no rating and a stop reason")
            if self.output_check != "NOT_RUN" or self.findings:
                raise ValueError("INCOMPLETE requires NOT_RUN and no findings")

    def as_dict(self) -> dict:
        return {
            "run_id": self.run_id, "ticker": self.ticker,
            "analysis_date": self.analysis_date, "input_mode": self.input_mode,
            "run_outcome": self.run_outcome, "stop_reason": self.stop_reason,
            "final_rating": self.final_rating, "output_check": self.output_check,
            "findings": [finding.as_dict() for finding in self.findings],
            "manifest_path": self.manifest_path, "report_path": self.report_path,
        }


@dataclass(frozen=True)
class RunRecord:
    """One evaluation attempt; kept outside the run manifest."""
    attempt_id: str
    category: Literal["STARTED", "PRE_RUN_REJECTED", "PRE_RUN_CANCELLED"]
    run_outcome: RunOutcome | None = None
    output_check: OutputCheck | None = None
    stop_reason: StopReason | None = None
    controlled_change: dict | None = None


def summarize_records(records: list[RunRecord]) -> dict:
    started = [r for r in records if r.category == "STARTED"]
    completed = [r for r in started if r.run_outcome == "COMPLETED"]
    incomplete = [r for r in started if r.run_outcome == "INCOMPLETE"]
    reasons: dict[str, int] = {}
    for record in incomplete:
        if record.stop_reason:
            reasons[record.stop_reason] = reasons.get(record.stop_reason, 0) + 1
    review_count = sum(r.output_check == "NEEDS_REVIEW" for r in completed)
    return {
        "status": "INSUFFICIENT_EVIDENCE" if not completed else "AVAILABLE",
        "started_count": len(started), "completed_count": len(completed),
        "completion_fraction": len(completed) / len(started) if started else None,
        "needs_review_count": review_count, "incomplete_reason_counts": reasons,
        "pre_run_rejected": sum(r.category == "PRE_RUN_REJECTED" for r in records),
        "pre_run_cancelled": sum(r.category == "PRE_RUN_CANCELLED" for r in records),
    }

