def cohort_controls():
    """The frozen analysis controls declared before any call (R2-04/R2-06).

    Returns ``{ticker, analysis_date, source_revision, prompt_hash}`` from the
    reviewed cohort. Missing controls are rejected for a formal cohort; when no
    cohort file exists (PENDING/no formal evidence yet) an empty mapping is
    returned and only defaults are used.
    """
    path = EVIDENCE_ROOT / "cohort.json"
    if not path.is_file():
        return {}
    cohort = _read(path)
    for key in ("ticker", "analysis_date"):
        value = cohort.get(key)
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"Cohort must declare a {key} control")
    return {
        "ticker": cohort["ticker"], "analysis_date": cohort["analysis_date"],
        "source_revision": cohort.get("source_revision"),
        "prompt_hash": cohort.get("prompt_hash"),
    }


